-- OBEC 2021 Arts M1 indicators
with seed(standard_code,code,name,seq,classification) as (values
('ศ 1.1','ARTS-M1-01','บรรยายความแตกต่างและความคล้ายคลึงกันของงานทัศนศิลป์และสิ่งแวดล้อมโดยใช้ความรู้เรื่องทัศนธาตุ',1,'should_know'),
('ศ 1.1','ARTS-M1-02','ระบุ และบรรยายหลักการออกแบบงานทัศนศิลป์ โดยเน้นความเป็นเอกภาพ ความกลมกลืน และความสมดุล',2,'must_know'),
('ศ 1.1','ARTS-M1-03','รวบรวมงานปั้นหรือสื่อผสมมาสร้างเป็นเรื่องราว ๓ มิติ โดยเน้นความเป็นเอกภาพ ความกลมกลืน และการสื่อถึงเรื่องราวของงาน',3,'should_know'),
('ศ 1.1','ARTS-M1-04','วาดภาพทัศนียภาพแสดงให้เห็นระยะใกล้ไกล เป็น ๓ มิติ',4,'must_know'),
('ศ 1.1','ARTS-M1-05','ออกแบบรูปภาพ สัญลักษณ์ หรือกราฟิกอื่น ๆ ในการนำเสนอความคิดเห็นและข้อมูล',5,'must_know'),
('ศ 1.1','ARTS-M1-06','ประเมินงานทัศนศิลป์ และบรรยายถึงวิธีการปรับปรุงงานของตนเองและผู้อื่นโดยใช้เกณฑ์ที่กำหนดให้',6,'must_know'),
('ศ 1.2','ARTS-M1-07','ระบุและบรรยายเกี่ยวกับลักษณะรูปแบบงานทัศนศิลป์ของชาติและของท้องถิ่นตนเองจากอดีตจนถึงปัจจุบัน',7,'must_know'),
('ศ 1.2','ARTS-M1-08','ระบุและเปรียบเทียบงานทัศนศิลป์ของภาคต่าง ๆ ในประเทศไทย',8,'should_know'),
('ศ 1.2','ARTS-M1-09','เปรียบเทียบความแตกต่างของจุดประสงค์ในการสร้างสรรค์งานทัศนศิลป์ของวัฒนธรรมไทยและสากล',9,'should_know'),
('ศ 2.1','ARTS-M1-10','อ่าน เขียน ร้องโน้ตไทยและโน้ตสากล',10,'should_know'),
('ศ 2.1','ARTS-M1-11','เปรียบเทียบเสียงร้องและเสียงของเครื่องดนตรีที่มาจากวัฒนธรรมที่ต่างกัน',11,'should_know'),
('ศ 2.1','ARTS-M1-12','ร้องเพลงและใช้เครื่องดนตรีบรรเลงประกอบการร้องเพลงด้วยบทเพลงที่หลากหลายรูปแบบ',12,'must_know'),
('ศ 2.1','ARTS-M1-13','จัดประเภทของวงดนตรีไทยและวงดนตรีที่มาจากวัฒนธรรมต่าง ๆ',13,'must_know'),
('ศ 2.1','ARTS-M1-14','แสดงความคิดเห็นที่มีต่ออารมณ์ของบทเพลงที่มีความเร็วของจังหวะและความดัง - เบาแตกต่างกัน',14,'must_know'),
('ศ 2.1','ARTS-M1-15','เปรียบเทียบอารมณ์ ความรู้สึกในการฟังดนตรีแต่ละประเภท',15,'must_know'),
('ศ 2.1','ARTS-M1-16','นำเสนอตัวอย่างเพลงที่ตนเองชื่นชอบและอภิปรายลักษณะเด่นที่ทำให้งานนั้นน่าชื่นชม',16,'should_know'),
('ศ 2.1','ARTS-M1-17','ใช้เกณฑ์สำหรับประเมินคุณภาพงานดนตรีหรือเพลงที่ฟัง',17,'must_know'),
('ศ 2.1','ARTS-M1-18','ใช้และบำรุงรักษาเครื่องดนตรีอย่างระมัดระวังและรับผิดชอบ',18,'should_know'),
('ศ 2.2','ARTS-M1-19','อธิบายบทบาทความสัมพันธ์และอิทธิพลของดนตรีที่มีต่อสังคมไทย',19,'must_know'),
('ศ 2.2','ARTS-M1-20','ระบุความหลากหลายขององค์ประกอบดนตรีในวัฒนธรรมต่างกัน',20,'should_know'),
('ศ 3.1','ARTS-M1-21','อธิบายอิทธิพลของนักแสดงชื่อดังที่มีผลต่อการโน้มน้าวอารมณ์หรือความคิดของผู้ชม',21,'should_know'),
('ศ 3.1','ARTS-M1-22','ใช้นาฏยศัพท์หรือศัพท์ทางการละครในการแสดง',22,'must_know'),
('ศ 3.1','ARTS-M1-23','แสดงนาฏศิลป์และละครในรูปแบบง่าย ๆ',23,'must_know'),
('ศ 3.1','ARTS-M1-24','ใช้ทักษะการทำงานเป็นกลุ่มในกระบวนการผลิตการแสดง',24,'should_know'),
('ศ 3.1','ARTS-M1-25','ใช้เกณฑ์ง่าย ๆ ที่กำหนดให้ในการพิจารณาคุณภาพการแสดงที่ชมโดยเน้นเรื่องการใช้เสียง การแสดงท่าและการเคลื่อนไหว',25,'should_know'),
('ศ 3.2','ARTS-M1-26','ระบุปัจจัยที่มีผลต่อการเปลี่ยนแปลงของนาฏศิลป์ นาฏศิลป์พื้นบ้านละครไทย และละครพื้นบ้าน',26,'must_know'),
('ศ 3.2','ARTS-M1-27','บรรยายประเภทของละครไทยในแต่ละยุคสมัย',27,'must_know')
), subj as (select t.id topic_id,t.code standard_code from learning_subjects s join learning_skills sk on sk.subject_id=s.id join learning_topics t on t.skill_id=sk.id where s.code='ARTS' and sk.code='ARTS'), ins as (insert into learning_objectives(topic_id,code,name,sequence_no) select subj.topic_id,seed.code,seed.name,seed.seq from seed join subj using(standard_code) on conflict(topic_id,code) do update set name=excluded.name,sequence_no=excluded.sequence_no returning id,code) insert into learning_objective_alignments(objective_id,curriculum_id,grade_level_id,required,indicator_classification) select o.id,c.id,g.id,(seed.classification='must_know'),seed.classification from seed join ins o on o.code=seed.code join learning_curricula c on c.code='TH-BASIC-CORE-2008-2017' join learning_grade_levels g on g.curriculum_id=c.id and g.code='M1' on conflict(objective_id,curriculum_id,grade_level_id) do update set required=excluded.required,indicator_classification=excluded.indicator_classification;